package org.sleepmonitor.app;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity{
 TextView values; Graph graph; Handler h=new Handler(); File selected; String diagnosticExport; WitSensor testWit;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,64,24,32);ScrollView scroll=new ScrollView(this);scroll.addView(l);setContentView(scroll);TextView title=new TextView(this);title.setText("SleepMonitor 2.1");title.setTextSize(30);l.addView(title);values=new TextView(this);values.setTextSize(23);l.addView(values);graph=new Graph();l.addView(graph,new LinearLayout.LayoutParams(-1,(int)(260*getResources().getDisplayMetrics().density)));TextView legend=new TextView(this);android.text.SpannableStringBuilder ls=new android.text.SpannableStringBuilder();String[] labels={"Rücken","Links","Rechts","Bauch","Unbekannt / Bewegung"};String[] keys={"Ruecken","Links","Rechts","Bauch","missing"};for(int i=0;i<labels.length;i++){int start=ls.length();ls.append("● "+labels[i]+"  ");ls.setSpan(new android.text.style.ForegroundColorSpan(graph.color(keys[i])),start,ls.length(),33);}legend.setText(ls);l.addView(legend);button(l,"Aufzeichnung starten",()->{if(permissions()){stopWitTest();startForegroundService(new Intent(this,MonitorService.class));}});button(l,"Aufzeichnung stoppen",()->stopService(new Intent(this,MonitorService.class)));button(l,"CSV exportieren",this::choose);button(l,"Körperlage kalibrieren",this::calibration);button(l,"WIT Einzeltest starten",()->{if(!permissions())return;if(MonitorService.running){Toast.makeText(this,"Zuerst Aufzeichnung stoppen",1).show();return;}stopWitTest();WitSensor.load(this);testWit=new WitSensor(this,h);testWit.start();});button(l,"WIT Einzeltest stoppen",this::stopWitTest);button(l,"WIT Diagnose exportieren",this::witExport);TextView note=new TextView(this);note.setText("Experimentelle Aufzeichnung – kein medizinischer Alarm. WIT-Sensor fest an der Brust befestigen. Lageerkennung experimentell. Messdaten bleiben lokal. Für die Messung andere Oximeter-Apps trennen.");l.addView(note);h.post(refresh);}
 void button(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());l.addView(b);}
 boolean permissions(){ArrayList<String> p=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){p.add("android.permission.BLUETOOTH_SCAN");p.add("android.permission.BLUETOOTH_CONNECT");}else p.add("android.permission.ACCESS_FINE_LOCATION");if(Build.VERSION.SDK_INT>=33)p.add("android.permission.POST_NOTIFICATIONS");ArrayList<String> missing=new ArrayList<>();for(String x:p)if(checkSelfPermission(x)!=PackageManager.PERMISSION_GRANTED)missing.add(x);if(!missing.isEmpty()){requestPermissions(missing.toArray(new String[0]),1);return false;}return true;}
 final Runnable refresh=new Runnable(){public void run(){boolean fresh=MonitorService.running&&System.currentTimeMillis()-MonitorService.last<3000;values.setText(MonitorService.status+"\nSpO₂: "+(fresh&&MonitorService.oxygen>0?MonitorService.oxygen+" %":"–")+"\nPuls: "+(fresh&&MonitorService.pulse>0?MonitorService.pulse+" bpm":"–")+"\nAkku: "+(fresh&&MonitorService.battery>=0?MonitorService.battery+" %":"–"));long seconds=MonitorService.started==0?0:(SystemClock.elapsedRealtime()-MonitorService.started)/1000;values.append("\nLaufzeit: "+String.format(Locale.US,"%02d:%02d:%02d",seconds/3600,(seconds/60)%60,seconds%60)+"\nEmpfangen: "+MonitorService.received+" | CSV-Zeilen: "+MonitorService.saved+"\nSpeicher: "+MonitorService.storage+"\nLetzte Speicherung: "+(MonitorService.lastSaved==0?"–":new java.text.SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date(MonitorService.lastSaved)))+"\nBLE-Neuverbindungen: "+MonitorService.disconnects);values.append("\n\n"+WitSensor.live());graph.invalidate();h.postDelayed(this,500);}};
 void calibration(){new AlertDialog.Builder(this).setTitle("Sensor fest montieren, ruhig liegen").setItems(new String[]{"Rückenlage","Bauchlage","Links","Rechts","Kalibrierung löschen"},(d,i)->{if(i==4){WitSensor.clear(this);return;}boolean ok=WitSensor.calibrate(this,i);Toast.makeText(this,ok?"Gespeichert":"Keine frischen ruhigen Daten oder Lage zu ähnlich",1).show();}).show();}
 void choose(){File[] fs=new File(getFilesDir(),"records").listFiles();if(fs==null||fs.length==0){Toast.makeText(this,"Keine Aufzeichnungen",0).show();return;}Arrays.sort(fs,Comparator.comparingLong(File::lastModified).reversed());String[] names=new String[fs.length];for(int i=0;i<fs.length;i++)names[i]=fs[i].getName();new AlertDialog.Builder(this).setTitle("Aufzeichnung auswählen").setItems(names,(d,i)->{selected=fs[i];Intent in=new Intent(Intent.ACTION_CREATE_DOCUMENT);in.setType("text/csv");in.addCategory(Intent.CATEGORY_OPENABLE);in.putExtra(Intent.EXTRA_TITLE,selected.getName());startActivityForResult(in,2);}).show();}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==3&&c==RESULT_OK&&d!=null&&diagnosticExport!=null){try(OutputStream out=getContentResolver().openOutputStream(d.getData())){out.write(diagnosticExport.getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"Diagnose gespeichert",0).show();}catch(Exception e){Toast.makeText(this,"Diagnoseexport fehlgeschlagen",1).show();}return;}if(r==2&&c==RESULT_OK&&d!=null&&selected!=null){try(InputStream in=new FileInputStream(selected);OutputStream out=getContentResolver().openOutputStream(d.getData())){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);Toast.makeText(this,"CSV gespeichert",0).show();}catch(Exception e){Toast.makeText(this,"Export fehlgeschlagen",1).show();}}}
 void witExport(){diagnosticExport=WitSensor.diagnostic();Intent in=new Intent(Intent.ACTION_CREATE_DOCUMENT);in.setType("text/plain");in.addCategory(Intent.CATEGORY_OPENABLE);in.putExtra(Intent.EXTRA_TITLE,"WIT-Diagnose-"+System.currentTimeMillis()+".txt");startActivityForResult(in,3);}
 void stopWitTest(){if(testWit!=null){testWit.stop();testWit=null;}}
 protected void onDestroy(){stopWitTest();h.removeCallbacksAndMessages(null);super.onDestroy();}
 class Graph extends View{
 Paint p=new Paint(3); final float dp=getResources().getDisplayMetrics().density;
 Graph(){super(MainActivity.this);}
 int color(String s){switch(s){case "Ruecken":return 0xffff5555;case "Links":return 0xff38cf70;case "Rechts":return 0xff529cff;case "Bauch":return 0xffffcf40;default:return 0xffaaaaaa;}}
 protected void onDraw(Canvas c){super.onDraw(c);float left=32*dp,right=getWidth()-20*dp,top=12*dp,bottom=getHeight()-30*dp;if(right<=left||bottom<=top)return;
 ArrayList<MonitorService.Point> a;long start;synchronized(MonitorService.history){a=new ArrayList<>(MonitorService.history);start=MonitorService.graphStart;}
 long end=a.isEmpty()?start:a.get(a.size()-1).time;if(MonitorService.running)end=Math.max(end,System.currentTimeMillis());if(start<=0)start=System.currentTimeMillis();end=Math.max(start+3600000L,end);
 float span=end-start; p.setTextSize(10*dp);p.setStrokeWidth(dp);p.setTextAlign(Paint.Align.RIGHT);
 for(int y=70;y<=100;y+=5){float yy=top+(100-y)*(bottom-top)/30;p.setColor(0xff999999);c.drawText(""+y,left-4*dp,yy+3*dp,p);p.setColor(0xff555555);c.drawLine(left,yy,right,yy,p);}
 java.util.Calendar cal=java.util.Calendar.getInstance();cal.setTimeInMillis(start);cal.set(java.util.Calendar.MINUTE,0);cal.set(java.util.Calendar.SECOND,0);cal.set(java.util.Calendar.MILLISECOND,0);if(cal.getTimeInMillis()<start)cal.add(java.util.Calendar.HOUR_OF_DAY,1);
 java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("HH:mm",Locale.getDefault());float lastLabel=-1000; p.setTextAlign(Paint.Align.CENTER);
 for(long t=cal.getTimeInMillis();t<=end;t+=3600000L){float x=left+(t-start)/span*(right-left);p.setColor(0xff777777);c.drawLine(x,top,x,bottom,p);c.drawLine(x,bottom,x,bottom+4*dp,p);if(x-lastLabel>=34*dp){p.setColor(0xffbbbbbb);c.drawText(fmt.format(new Date(t)),x,bottom+16*dp,p);lastLabel=x;}}
 c.save();c.clipRect(left,top,right,bottom);p.setStrokeWidth(1.7f*dp);
 for(int i=0;i<a.size();i++){MonitorService.Point q=a.get(i);float x=left+(q.time-start)/span*(right-left),y=top+(100-Math.max(70,q.oxygen))*(bottom-top)/30;p.setColor(color(q.position));if(i>0){MonitorService.Point prev=a.get(i-1);if(q.time>prev.time&&q.time-prev.time<=3000){float px=left+(prev.time-start)/span*(right-left),py=top+(100-Math.max(70,prev.oxygen))*(bottom-top)/30;float mx=(px+x)/2,my=(py+y)/2;p.setColor(color(prev.position));c.drawLine(px,py,mx,my,p);p.setColor(color(q.position));c.drawLine(mx,my,x,y,p);continue;}}c.drawPoint(x,y,p);}c.restore();p.setTextAlign(Paint.Align.LEFT);
 }
 }
}
